import re
from functools import partial
from .exception import MultipleSetupMethodsFound, MultipleTeardownMethodsFound
from .exception import SetupMethodNotFound, TeardownMethodNotFound


class NewSession(object):
    """Sets new context session for given instance."""

    def __init__(self, instance, setup, teardown, **kwargs):
        self.instance = instance
        self.setup_method = setup
        self.teardown_method = teardown
        self.kw = kwargs

    def __enter__(self):
        self.setup_method()
        return self.instance

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.teardown_method()


class NewUteSession(NewSession):
    """ Sets new context for ute libraries. Methods with setup and teardown prefix have to be implemented."""

    def __init__(self, ute_lib_instance, **kwargs):
        self.instance = ute_lib_instance
        setup = self._build_setup_object(**kwargs)
        teardown = self._build_teardown_object(**kwargs)
        super(NewUteSession, self).__init__(self.instance, setup, teardown)

    def _build_setup_object(self, **kwargs):
        setup_methods = [method for method in dir(self.instance) if re.search('setup_*', method)]
        if len(setup_methods) > 1:
            raise MultipleSetupMethodsFound()
        elif len(setup_methods) == 0:
            raise SetupMethodNotFound()
        setup = getattr(self.instance, setup_methods[0])
        return partial(setup, **kwargs)

    def _build_teardown_object(self, **kwargs):
        teardown_methods = [method for method in dir(self.instance) if re.search('teardown_(?!all_)', method)]
        if len(teardown_methods) > 1:
            raise MultipleTeardownMethodsFound()
        elif len(teardown_methods) == 0:
            raise TeardownMethodNotFound()
        teardown = getattr(self.instance, teardown_methods[0])
        return partial(teardown, alias=kwargs.get('alias'))
